!function(e){function r(r){for(var p,n,a=r[0],c=r[1],d=r[2],s=0,l=[];s<a.length;s++)n=a[s],Object.prototype.hasOwnProperty.call(i,n)&&i[n]&&l.push(i[n][0]),i[n]=0;for(p in c)Object.prototype.hasOwnProperty.call(c,p)&&(e[p]=c[p]);for(u&&u(r);l.length;)l.shift()();return o.push.apply(o,d||[]),t()}function t(){for(var e,r=0;r<o.length;r++){for(var t,n=o[r],a=!0,c=1;c<n.length;c++)t=n[c],0!==i[t]&&(a=!1);a&&(o.splice(r--,1),e=p(p.s=n[0]))}return e}function p(r){if(n[r])return n[r].exports;var t=n[r]={i:r,l:!1,exports:{}};return e[r].call(t.exports,t,t.exports,p),t.l=!0,t.exports}var n={},i={56:0},o=[];p.m=e,p.c=n,p.d=function(e,r,t){p.o(e,r)||Object.defineProperty(e,r,{enumerable:!0,get:t})},p.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},p.t=function(e,r){if(1&r&&(e=p(e)),8&r)return e;if(4&r&&"object"==typeof e&&e&&e.__esModule)return e;var t=Object.create(null);if(p.r(t),Object.defineProperty(t,"default",{enumerable:!0,value:e}),2&r&&"string"!=typeof e)for(var n in e)p.d(t,n,function(r){return e[r]}.bind(null,n));return t},p.n=function(e){var r=e&&e.__esModule?function(){return e.default}:function(){return e};return p.d(r,"a",r),r},p.o=function(e,r){return Object.prototype.hasOwnProperty.call(e,r)},p.p="";var a=window.webpackJsonp=window.webpackJsonp||[],c=a.push.bind(a);a.push=r,a=a.slice();for(var d=0;d<a.length;d++)r(a[d]);var u=c;o.push([228,0]),t()}({228:function(e,r,t){"use strict";t.r(r);var p=t(0);Object(p.a)("de","army",t(229),t(1))},229:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"轻武器","link":"de_army#de_army_iw"}],"model":"G41、G43半自动步枪","description":"<p>德军入侵苏联后，在实战中很快就感觉到其步兵的98K制式步枪经常受到苏军SVT半自动步枪快速密集火力的压制，因此对半自动步枪也产生了迫切需求，进而加紧了对半自动步枪的研制，最早生产出来的是G41(Gew41)型半自动步枪，但该型枪虽然火力性能比98K步枪有提高，但由于装弹困难，枪机容易失灵，以及在苏联低温严寒和北非酷热沙尘的恶劣环境下出现枪管难以清洗和维护等问题，因此并不受德国陆军士兵的欢迎，为此于1943年，德军在G41的基础上改进研制了G43（Gew43）型半自动步枪（1944年改名为K43）。</p><p>G43半自动步枪具有半自动枪机与10发装弹匣，能够在不频繁拉动枪栓上膛造成射击中断的情况下快速射击目标，其枪管较短也便于携带，在装上瞄准镜后又能作半自动狙击步枪使用，的确是填补了德军半自动火力的空白，但由于其射速不如冲锋枪，射击精度又不如98K步枪，因此该型枪装备德军后，士兵对其的评价是好坏参半。</p><p>二战期间，G41半自动步枪一共生产了122907支，而G43半自动步枪总产为402713支，但对于有几百万士兵的德国陆军来说，这个数量远难满足部队需求，因此在当时有配备G43半自动步枪手的部队中，每个班通常也只能分配到一支该型枪。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_iwG4143_11.jpg","description":"<p>技术数据：</p><h6>G41半自动步枪</h6><p></p><p>口径：7.92毫米；</p><p>全长：1140毫米，枪管长：546毫米，重量：4.9千克；</p><p>最大射速：30发/分钟；</p><p>有效射程：400米；</p><p>弹匣容量：10发。</p><h6>G43半自动步枪</h6><p></p><p>口径：7.92毫米；</p><p>全长：1130毫米，枪管长：550毫米，重量：4.4千克；</p><p>最大射速：60发/分钟；</p><p>有效射程：500米；</p><p>弹匣容量：10发。</p>","caption":""}],"part2title":"战场上的G41、G43半自动步枪","part2description":"","part2content":[{"image":"imgs/de/army/de_army_iwG4143_21.jpg","description":"二战战场上手持G43半自动步枪的德军士兵。左边两名士兵是半自动步枪狙击手，所持的G43配有光学瞄准镜。","caption":""},{"image":"imgs/de/army/de_army_iwG4143_22.jpg","description":"1943年10月，德国一间步兵学校射击场上，一名德军士兵正在进行G43半自动步枪的测试。","caption":""},{"image":"imgs/de/army/de_army_iwG4143_23.jpg","description":"1943年冬天，西线意大利战场，德军一支自行车部队在泥泞山路上行进。队伍后方的一名士兵背着G43半自动步枪。","caption":""},{"image":"imgs/de/army/de_army_iwG4143_24.jpg","description":"1944年2月，东线苏联战场，“切尔卡瑟”战役结束后，从苏军包围圈中突围出来的一名德国武装党卫军中士向一名连长讲述突围战斗中的激烈战况，连其手中的G41半自动步枪也都中弹了。","caption":""},{"image":"imgs/de/army/de_army_iwG4143_25.jpg","description":"1944年冬天，东线战场，一名德军士兵在战壕中用G43半自动步枪抵抗苏军的进攻。","caption":""},{"image":"imgs/de/army/de_army_iwG4143_26.jpg","description":"1945年春天，德国本土战场，聚集一处的几位德军“赫尔曼·戈林”师狙击枪手，他们大部份配备的都是带光学瞄准镜的G43半自动步枪。","caption":""}]}')}});